-- Click-to-type blanks for the thirteen built-in templates that never got any.
--
-- Client feedback on the Electrical Installation and Test Report: "This is a
-- nice change from squiggly lines. Please ensure all templates are easy like
-- this." The squiggly lines are gone everywhere already, because the resolver
-- degrades an unfillable `{{token}}` to `[Field name]` and
-- `bracketsToFillFields` turns that into a labelled box. What it cannot do is
-- invent a box where the template never asked a question.
--
-- That is the split this file closes. Nine trade templates (20260820000000)
-- were authored with `[Permit number]`, `[Date]`, `[Name]` blanks, which is the
-- one the client was looking at. The twelve from the original library
-- (20260803000001) plus HVAC Installation and Start-Up were not, so their
-- identity tables arrived as bare cells - and worse, several carried the hint
-- as ordinary text ("Residential / commercial", "Temp / wind / dry or wet"),
-- which is not a prompt but an answer already typed in. Left alone it prints
-- into the customer's PDF as though the inspector had written it.
--
-- What changed, and only this:
--
--   * every fixed-fact table - one `<th>` label per row, or a header row with a
--     single data row under it - now holds a labelled blank per value cell;
--   * a cell that carried hint text keeps that wording as the blank's label,
--     so the guidance survives but the text no longer has to be deleted first;
--   * Site Visit Report and HVAC Installation and Start-Up had no fixed-fact
--     table at all, so they gain the same identity block their siblings open
--     with. HVAC Installation was the only one of the nine trade templates
--     that shipped without blanks.
--
-- What deliberately did not change: grids you add rows to (circuit schedules,
-- parts lists, timesheets, readings) stay empty, and so do sign-off tables.
-- That is what the hand-written trade templates do - sitepix-hvac-service-call
-- labels ten rows of readings and leaves all thirty value cells blank - and a
-- dashed box in every cell of a ten-row grid is thirty boxes to clear.
--
-- Bodies only. Every slug, name, category, description and fields array is
-- carried over unchanged from the migration that seeded it, so the picker's
-- grouping and the Templates page's cards are untouched. Photo slots, task
-- lists, tables and merge tokens are preserved count-for-count, which
-- tests/document-template-library.test.ts checks against these rows.
--
-- Idempotent - ON CONFLICT (slug) DO UPDATE. Safe to re-run.
-- Apply via the SitePix Supabase SQL editor (or `supabase db push`).

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-site-visit-report',
  NULL,
  NULL,
  'Site Visit Report',
  jsonb_build_object(
    'style', 'report',
    'category', 'Field Reports',
    'description', 'A walk-the-site report organised by what you found, what you did, and what happens next - with a title page for the client.',
    'html', $html$<hr><h1 style="text-align:center"><span style="font-size: 34px">{{project_name}}</span></h1><p style="text-align:center"><span style="color: rgb(107,114,128)">{{project_address}}</span></p><p style="text-align:center"><span style="color: rgb(156,163,175)">Site visit &nbsp;·&nbsp; {{date}}</span></p><p style="height: 520px"></p><p style="text-align:center"><strong>{{company}}</strong></p><p style="text-align:center"><span style="font-size: 12px; color: rgb(156,163,175)">{{company_address}}</span></p><p style="text-align:center"><span style="font-size: 12px; color: rgb(156,163,175)">{{company_phone}} &nbsp;·&nbsp; Prepared by {{prepared_by}}</span></p><hr><h2>Visit details</h2><table><tbody><tr><th><p>Attended by</p></th><th><p>Met on site</p></th><th><p>Work order #</p></th><th><p>On site</p></th><th><p>Off site</p></th></tr><tr><td><p>[Name]</p></td><td><p>[Who you met]</p></td><td><p>[WO number]</p></td><td><p>[Time]</p></td><td><p>[Time]</p></td></tr></tbody></table><h2>Overview</h2><p><em><span style="color: rgb(140,148,162)">Why were you on site, who did you meet, and what was the overall condition?</span></em></p><p></p><h2>What we found</h2><p><em><span style="color: rgb(140,148,162)">One line per issue. Add the photo that proves it.</span></em></p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EWide%20shot%20-%20whole%20area%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Wide shot - whole area"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EClose-up%20-%20the%20issue%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Close-up - the issue"></p><p></p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EWide%20shot%20-%20whole%20area%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Wide shot - whole area"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'mid