  jsonb_build_object(
    'style', 'report',
    'category', 'Field Reports',
    'description', 'A dense, caption-per-photo record for days when the photos are the report. Numbered so anyone can reference a shot by number.',
    'html', $html$<h1>Photo Log</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><p><em><span style="color: rgb(140,148,162)">Everything captured on this visit, in order. Caption each shot so it stands on its own months from now.</span></em></p><h3>1.</h3><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'720'%20height%3D'300'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'719'%20height%3D'299'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'360'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EPhoto%3C%2Ftext%3E%3Ctext%20x%3D'360'%20y%3D'164'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="100%" height="300" alt="Photo"></p><table><tbody><tr><th><p>Location</p></th><th><p>What it shows</p></th><th><p>Action needed</p></th></tr><tr><td><p>[Location]</p></td><td><p>[What it shows]</p></td><td><p>[Action needed]</p></td></tr></tbody></table><h3>2.</h3><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'720'%20height%3D'300'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'719'%20height%3D'299'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'360'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EPhoto%3C%2Ftext%3E%3Ctext%20x%3D'360'%20y%3D'164'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="100%" height="300" alt="Photo"></p><table><tbody><tr><th><p>Location</p></th><th><p>What it shows</p></th><th><p>Action needed</p></th></tr><tr><td><p>[Location]</p></td><td><p>[What it shows]</p></td><td><p>[Action needed]</p></td></tr></tbody></table><h3>3.</h3><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'720'%20height%3D'300'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'719'%20height%3D'299'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'360'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EPhoto%3C%2Ftext%3E%3Ctext%20x%3D'360'%20y%3D'164'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="100%" height="300" alt="Photo"></p><table><tbody><tr><th><p>Location</p></th><th><p>What it shows</p></th><th><p>Action needed</p></th></tr><tr><td><p>[Location]</p></td><td><p>[What it shows]</p></td><td><p>[Action needed]</p></td></tr></tbody></table><h3>4.</h3><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'720'%20height%3D'300'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'719'%20height%3D'299'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'360'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EPhoto%3C%2Ftext%3E%3Ctext%20x%3D'360'%20y%3D'164'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="100%" height="300" alt="Photo"></p><table><tbody><tr><th><p>Location</p></th><th><p>What it shows</p></th><th><p>Action needed</p></th></tr><tr><td><p>[Location]</p></td><td><p>[What it shows]</p></td><td><p>[Action needed]</p></td></tr></tbody></table><hr><h2>Summary</h2><p><em><span style="color: rgb(140,148,162)">Anything the photos don't say on their own?</span></em></p><p></p>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
