INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-daily-site-report',
  NULL,
  NULL,
  'Daily Site Report',
  jsonb_build_object(
    'style', 'report',
    'category', 'Field Reports',
    'description', 'End-of-day record of who worked, what arrived, what got done, and what''''s holding things up. Built for a running daily file.',
    'html', $html$<h1>Daily Site Report</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><table><tbody><tr><th><p>Superintendent</p></th><td><p>[Superintendent]</p></td></tr><tr><th><p>Hours on site</p></th><td><p>[Hours on site]</p></td></tr><tr><th><p>Weather</p></th><td><p>[Temp / wind / conditions]</p></td></tr><tr><th><p>Permit #</p></th><td><p>[Permit #]</p></td></tr></tbody></table><hr><h2>Who worked today</h2><table><tbody><tr><th><p>Trade</p></th><th><p>Company</p></th><th><p>Headcount</p></th><th><p>Hours</p></th><th><p>What they worked on</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Deliveries &amp; equipment</h2><table><tbody><tr><th><p>Time</p></th><th><p>Item</p></th><th><p>Qty</p></th><th><p>Received by</p></th><th><p>Condition</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Progress</h2><table><tbody><tr><th><p>Area / trade</p></th><th><p>Scope completed</p></th><th><p>% done</p></th><th><p>Inspected by</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EProgress%20-%20area%201%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Progress - area 1"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EProgress%20-%20area%202%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Progress - area 2"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EProgress%20-%20area%203%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Progress - area 3"></p><h2>Safety walk</h2><p><em><span style="color: rgb(140,148,162)">OSHA 29 CFR 1926 subparts relevant to today's work.</span></em></p><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Toolbox talk held</p></li><li data-type="taskItem" data-checked="false"><p>Fall protection in place where required (1926.501)</p></li><li data-type="taskItem" data-checked="false"><p>Excavations 5 ft or deeper protected (1926.652)</p></li><li data-type="taskItem" data-checked="false"><p>Housekeeping clear - no trip or puncture hazards</p></li><li data-type="taskItem" data-checked="false"><p>First aid and eyewash stocked and reachable</p></li><li data-type="taskItem" data-checked="false"><p>Any incident or near-miss written up</p></li></ul><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3ESite%20conditions%20%2F%20signage%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Site conditions / signage"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EAnything%20unsafe%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Anything unsafe"></p><h2>Delays, RFIs &amp; changes</h2><table><tbody><tr><th><p>Raised</p></th><th><p>Issue</p></th><th><p>RFI #</p></th><th><p>Sent to</p></th><th><p>Reply due</p></th><th><p>Schedule impact</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><p><strong>Terms &amp; conditions</strong></p><p><em><span style="color: rgb(140,148,162)">Drop in your standard site-reporting terms from the Snippets menu in the toolbar, or type them here once and save them as a snippet for next time.</span></em></p><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Superintendent</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Owner / Rep</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-claim-log-timeline',
  NULL,
  NULL,
  'Claim Log & Timeline',
  jsonb_build_object(
    'style', 'report',
    'category', 'Insurance & Adjusting',
    'description', 'Running contact log and dated timeline for a claim file - every call, letter, and decision in one defensible record.',
    'html', $html$<h1>Claim Log &amp; Timeline</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><table><tbody><tr><th><p>Claim #</p></th><td><p>[Claim #]</p></td></tr><tr><th><p>Policy #</p></th><td><p>[Policy #]</p></td></tr><tr><th><p>Insured</p></th><td><p>[Insured]</p></td></tr><tr><th><p>Date of loss</p></th><td><p>[Date of loss]</p></td></tr><tr><th><p>Cause of loss</p></th><td><p>[Cause of loss]</p></td></tr><tr><th><p>Adjuster</p></th><td><p>[Adjuster]</p></td></tr><tr><th><p>Limitation date</p></th><td><p>[Limitation date]</p></td></tr></tbody></table><hr><h2>What was damaged</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Roof / envelope</p></li><li data-type="taskItem" data-checked="false"><p>Structure</p></li><li data-type="taskItem" data-checked="false"><p>Interior &amp; contents</p></li><li data-type="taskItem" data-checked="false"><p>Business interruption / additional living expense</p></li><li data-type="taskItem" data-checked="false"><p>Third-party liability</p></li></ul><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EOverall%20property%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Overall property"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EPrimary%20damage%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Primary damage"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3ESecondary%20damage%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Secondary damage"></p><h2>Contact log</h2><p><em><span style="color: rgb(140,148,162)">Every touchpoint on this claim, newest at the bottom.</span></em></p><table><tbody><tr><th><p>Date / time</p></th><th><p>Who</p></th><th><p>Call, email or visit</p></th><th><p>What was agreed</p></th><th><p>Next action</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Issued &amp; requested</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Coverage position letter issued</p></li><li data-type="taskItem" data-checked="false"><p>Reservation of rights sent</p></li><li data-type="taskItem" data-checked="false"><p>Statement of loss drafted</p></li><li data-type="taskItem" data-checked="false"><p>Engineer or specialist report requested</p></li></ul><h2>Timeline of the loss</h2><p><em><span style="color: rgb(140,148,162)">The sequence of events as established, independent of the contact log above.</span></em></p><table><tbody><tr><th><p>Date</p></th><th><p>What happened</p></th><th><p>Established from</p></th><th><p>Effect on the claim</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><p><strong>Terms &amp; conditions</strong></p><p><em><span style="color: rgb(140,148,162)">Drop in your standard claims-handling terms and retention policy from the Snippets menu in the toolbar, or type them here once and save them as a snippet for next time.</span></em></p><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Adjuster</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Supervisor</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-property-damage-scope',
  NULL,
  NULL,
  'Property Damage Scope',
  jsonb_build_object(
    'style', 'report',
    'category', 'Insurance & Adjusting',
    'description', 'Component-by-component damage assessment with replacement and actual cash value, mitigation status, and a coverage recommendation.',
    'html', $html$<h1>Property Damage Scope</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><table><tbody><tr><th><p>Claim #</p></th><td><p>[Claim #]</p></td></tr><tr><th><p>Insured / location</p></th><td><p>[Insured / location]</p></td></tr><tr><th><p>Building type</p></th><td><p>[Building type]</p></td></tr><tr><th><p>Year built</p></th><td><p>[Year built]</p></td></tr><tr><th><p>Occupancy at time of loss</p></th><td><p>[Occupancy at time of loss]</p></td></tr><tr><th><p>Adjuster</p></th><td><p>[Adjuster]</p></td></tr></tbody></table><hr><h2>Damage by component</h2><table><tbody><tr><th><p>Component</p></th><th><p>Condition before loss</p></th><th><p>Damage observed</p></th><th><p>Qty / area</p></th><th><p>RCV</p></th><th><p>ACV</p></th><th><p>Code upgrade</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h3>Evidence</h3><p><em><span style="color: rgb(140,148,162)">One photo per component above - annotate directly on the photo where it helps.</span></em></p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EComponent%201%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Component 1"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EComponent%202%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Component 2"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EComponent%203%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Component 3"></p><h2>Mitigation underway</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Dry-out in progress</p></li><li data-type="taskItem" data-checked="false"><p>Board-up / temporary weather protection complete</p></li><li data-type="taskItem" data-checked="false"><p>Demolition authorised</p></li><li data-type="taskItem" data-checked="false"><p>Contents packed out</p></li><li data-type="taskItem" data-checked="false"><p>Moisture map attached (IICRC S500)</p></li><li data-type="taskItem" data-checked="false"><p>Structural engineer engaged</p></li></ul><h2>Cost summary</h2><table><tbody><tr><th><p>Area</p></th><th><p>Material</p></th><th><p>Qty / dimensions</p></th><th><p>Detail</p></th><th><p>RCV</p></th><th><p>ACV</p></th><th><p>Depreciation</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><p><strong>Advance payment requested:</strong> <span style="color: rgb(140,148,162)">optional - amount and reason</span></p><h2>Coverage recommendation</h2><p><em><span style="color: rgb(140,148,162)">Which policy sections, exclusions and endorsements apply, and what you recommend.</span></em></p><p></p><p><strong>Terms &amp; conditions</strong></p><p><em><span style="color: rgb(140,148,162)">Drop in your standard coverage language from the Snippets menu in the toolbar, or type them here once and save them as a snippet for next time.</span></em></p><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Adjuster</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Insured / Rep</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-restoration-scope',
  NULL,
  NULL,
  'Water & Mold Restoration Scope',
  jsonb_build_object(
    'style', 'report',
    'category', 'Restoration',
    'description', 'Room-by-room moisture readings, drying equipment log, and a line-item scope - structured around IICRC S500 drying protocol.',
    'html', $html$<h1>Water &amp; Mold Restoration Scope</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><table><tbody><tr><th><p>Claim #</p></th><td><p>[Claim #]</p></td></tr><tr><th><p>Water category</p></th><td><p>[1 clean / 2 grey / 3 black]</p></td></tr><tr><th><p>Class of loss</p></th><td><p>[Class of loss (1-4)]</p></td></tr><tr><th><p>Building use</p></th><td><p>[Building use]</p></td></tr><tr><th><p>Adjuster / project manager</p></th><td><p>[Adjuster / project manager]</p></td></tr><tr><th><p>First inspection</p></th><td><p>[First inspection]</p></td></tr></tbody></table><hr><h2>Room by room</h2><table><tbody><tr><th><p>Room / area</p></th><th><p>Material affected</p></th><th><p>Moisture reading</p></th><th><p>Dry standard</p></th><th><p>Remove?</p></th><th><p>Code upgrade?</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><p><em><span style="color: rgb(140,148,162)">Readings taken per IICRC S500 Table 12-1 - note pin or non-invasive meter against the dry standard for each material.</span></em></p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EAffected%20area%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Affected area"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EMeter%20reading%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Meter reading"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3ESource%20of%20loss%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Source of loss"></p><h2>Containment &amp; air</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Containment built - 6 mil poly, negative pressure</p></li><li data-type="taskItem" data-checked="false"><p>Pre-filter and HEPA filter logged with change dates</p></li><li data-type="taskItem" data-checked="false"><p>Air movers and dehumidifiers sized (AHAM)</p></li><li data-type="taskItem" data-checked="false"><p>Affected occupants notified</p></li></ul><h2>Drying log</h2><p><em><span style="color: rgb(140,148,162)">One row per equipment check. Daily readings are what prove the structure reached dry standard.</span></em></p><table><tbody><tr><th><p>Day</p></th><th><p>Equipment on site</p></th><th><p>AHAM</p></th><th><p>RH %</p></th><th><p>GPP</p></th><th><p>Temp</p></th><th><p>Tech</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Scope &amp; pricing</h2><table><tbody><tr><th><p>Line</p></th><th><p>Code</p></th><th><p>Description</p></th><th><p>Qty</p></th><th><p>Unit</p></th><th><p>Cost</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><p><strong>Subtotal</strong></p><p>Overhead</p><p>Profit</p><p><strong>Total</strong></p><hr><h2>Protocol notes</h2><ul><li><p>Drying carried out to IICRC S500 (current edition); mould remediation to IICRC S520.</p></li><li><p>Hidden damage found after demolition will be scoped as a change order before work continues.</p></li></ul><p><strong>Terms &amp; conditions</strong></p><p><em><span style="color: rgb(140,148,162)">Drop in your standard restoration terms from the Snippets menu in the toolbar, or type them here once and save them as a snippet for next time.</span></em></p><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Project manager</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Adjuster / Insured</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-roof-condition-survey',
  NULL,
  NULL,
  'Roof Condition Survey',
  jsonb_build_object(
    'style', 'report',
    'category', 'Roofing & Exterior',
    'description', 'Slope-by-slope condition survey with test cuts, flashing status, remaining life estimate, and a repair-or-replace recommendation.',
    'html', $html$<h1>Roof Condition Survey</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><table><tbody><tr><th><p>Building</p></th><td><p>[Residential / commercial]</p></td></tr><tr><th><p>Roof system</p></th><td><p>[Steep-slope / low-slope]</p></td></tr><tr><th><p>Roof area (squares)</p></th><td><p>[Roof area (squares)]</p></td></tr><tr><th><p>Inspector / certification #</p></th><td><p>[Inspector / certification #]</p></td></tr><tr><th><p>Conditions</p></th><td><p>[Temp / wind / dry or wet]</p></td></tr></tbody></table><hr><h2>Before going up</h2><p><em><span style="color: rgb(140,148,162)">OSHA 29 CFR 1926 subpart M - fall protection.</span></em></p><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Fall protection in place - harness, guardrail or safety monitor</p></li><li data-type="taskItem" data-checked="false"><p>Ladder tied off and extending 3 ft above the eave</p></li><li data-type="taskItem" data-checked="false"><p>Deck dry, no ice, no storm risk in the window</p></li><li data-type="taskItem" data-checked="false"><p>Hard hat, high-vis and boots on</p></li></ul><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3ELadder%20set%20%26amp%3B%20tie-off%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" 