  jsonb_build_object(
    'style', 'report',
    'category', 'Roofing & Exterior',
    'description', 'Closes out a roofing job: final costs, completion photos, and the manufacturer and workmanship warranty details in one handover document.',
    'html', $html$<h1>Roofing Completion &amp; Warranty</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><table><tbody><tr><th><p>Invoice #</p></th><td><p>[Invoice #]</p></td></tr><tr><th><p>Contract #</p></th><td><p>[Contract #]</p></td></tr><tr><th><p>Work completed</p></th><td><p>[Work completed]</p></td></tr><tr><th><p>Contractor licence #</p></th><td><p>[Contractor licence #]</p></td></tr><tr><th><p>Manufacturer certification</p></th><td><p>[Manufacturer certification]</p></td></tr></tbody></table><hr><h2>Bill to</h2><p><em><span style="color: rgb(140,148,162)">Owner or property manager, billing address, and best contact.</span></em></p><p></p><h2>Work completed &amp; final costs</h2><table><tbody><tr><th><p>Line</p></th><th><p>Description</p></th><th><p>Qty</p></th><th><p>Unit</p></th><th><p>Total</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><table><tbody><tr><th><p></p></th><th><p>Amount</p></th></tr><tr><td><p><strong>Subtotal</strong></p></td><td><p><strong></strong></p></td></tr><tr><td><p>Approved change orders</p></td><td><p></p></td></tr><tr><td><p>Tax</p></td><td><p></p></td></tr><tr><td><p>Less deposits and progress payments</p></td><td><p></p></td></tr><tr><td><p><strong>Balance due</strong></p></td><td><p><strong></strong></p></td></tr></tbody></table><p><em><span style="color: rgb(140,148,162)">Send this as a payment request from the share menu to collect the balance by card or ACH.</span></em></p><h2>Proof of completion</h2><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EFinished%20roof%20-%20front%20elevation%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Finished roof - front elevation"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EFinished%20roof%20-%20rear%20elevation%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Finished roof - rear elevation"></p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3ERidge%20%26amp%3B%20ventilation%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Ridge &amp;amp; ventilation"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EFlashing%20%26amp%3B%20penetrations%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Flashing &amp;amp; penetrations"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3ESite%20left%20clean%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Site left clean"></p><h2>Warranty</h2><table><tbody><tr><th><p>Manufacturer &amp; product</p></th><td><p>[Manufacturer and product]</p></td></tr><tr><th><p>Colour</p></th><td><p>[Colour]</p></td></tr><tr><th><p>Batch / lot #</p></th><td><p>[Batch / lot #]</p></td></tr><tr><th><p>Installed</p></th><td><p>[Installed]</p></td></tr><tr><th><p>Wind rating</p></th><td><p>[Wind rating]</p></td></tr><tr><th><p>Algae / staining cover</p></th><td><p>[Algae / staining cover]</p></td></tr><tr><th><p>Workmanship cover</p></th><td><p>[Workmanship cover]</p></td></tr><tr><th><p>Manufacturer registration #</p></th><td><p>[Manufacturer registration #]</p></td></tr></tbody></table><ul><li><p>Warranty activates once the balance clears and manufacturer registration is filed.</p></li><li><p>Keep this document - the batch number and registration number are needed for any future claim.</p></li></ul><p><strong>Terms &amp; conditions</strong></p><p><em><span style="color: rgb(140,148,162)">Drop in your standard payment and warranty terms from the Snippets menu in the toolbar, or type them here once and save them as a snippet for next time.</span></em></p><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Project manager</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Owner / Rep</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-cleaning-job-signoff',
  NULL,
  NULL,
  'Cleaning Job Sign-Off',
  jsonb_build_object(
    'style', 'report',
    'category', 'Cleaning',
    'description', 'Area-by-area task checklist plus a quality walk with the client, ending in a signature that the scope was met.',
    'html', $html$<h1>Cleaning Job Sign-Off</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><table><tbody><tr><th><p>Job / work order #</p></th><td><p>[Job / work order #]</p></td></tr><tr><th><p>Crew lead</p></th><td><p>[Crew lead]</p></td></tr><tr><th><p>On site</p></th><td><p>[On site]</p></td></tr><tr><th><p>Safety data sheets on site</p></th><td><p>[Yes / no]</p></td></tr></tbody></table><hr><h2>Scope by area</h2><p><em><span style="color: rgb(140,148,162)">One row per room or zone. Record the product and dilution actually used - it matters if anyone asks later.</span></em></p><table><tbody><tr><th><p>Area</p></th><th><p>Task</p></th><th><p>Product &amp; dilution</p></th><th><p>PPE used</p></th><th><p>Done</p></th><th><p>Photo</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Before leaving</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Debris removed from the site perimeter</p></li><li data-type="taskItem" data-checked="false"><p>High-touch surfaces disinfected - handles, switches, rails</p></li><li data-type="taskItem" data-checked="false"><p>Floors dry, wet-floor signs collected</p></li><li data-type="taskItem" data-checked="false"><p>Air scrubbers and equipment off-hired</p></li><li data-type="taskItem" data-checked="false"><p>Waste and PPE disposed of correctly</p></li></ul><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EFinished%20area%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Finished area"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EWaste%20removed%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Waste removed"></p><h2>Quality walk with the client</h2><table><tbody><tr><th><p>Check</p></th><th><p>Pass</p></th><th><p>Notes</p></th></tr><tr><td><p>Surfaces clean and streak-free</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>No chemical odour remaining</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Equipment and materials removed</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Client walked the space</p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Client acceptance</h2><p>The scope above was completed to my satisfaction.</p><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Client / Rep</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Crew lead</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><p><strong>Terms &amp; conditions</strong></p><p><em><span style="color: rgb(140,148,162)">Drop in your standard scope exclusions, re-clean window and liability from the Snippets menu in the toolbar, or type them here once and save them as a snippet for next time.</span></em></p>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-cleaning-invoice-photos',
  NULL,
  NULL,
  'Cleaning Invoice with Proof Photos',
  jsonb_build_object(
    'style', 'report',
    'category', 'Cleaning',
    'description', 'An itemised cleaning invoice that carries its own before-and-after evidence, so the bill and the proof travel together.',
    'html', $html$<h1>Cleaning Invoice</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><table><tbody><tr><th><p>Invoice #</p></th><td><p>[Invoice #]</p></td></tr><tr><th><p>Invoice date</p></th><td><p>[Invoice date]</p></td></tr><tr><th><p>Payment due</p></th><td><p>[Payment due]</p></td></tr><tr><th><p>Job / work order #</p></th><td><p>[Job / work order #]</p></td></tr></tbody></table><hr><h2>Bill to</h2><p><em><span style="color: rgb(140,148,162)">Client name, site address, and billing contact.</span></em></p><p></p><h2>Services provided</h2><table><tbody><tr><th><p>#</p></th><th><p>Service</p></th><th><p>Qty / hours</p></th><th><p>Rate</p></th><th><p>Total</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><table><tbody><tr><th><p></p></th><th><p>Amount</p></th></tr><tr><td><p><strong>Subtotal</strong></p></td><td><p><strong></strong></p></td></tr><tr><td><p>Consumables &amp; PPE</p></td><td><p></p></td></tr><tr><td><p>Waste disposal</p></td><td><p></p></td></tr><tr><td><p>Tax</p></td><td><p></p></td></tr><tr><td><p><strong>Total due</strong></p></td><td><p><strong></strong></p></td></tr></tbody></table><h2>Payment</h2><ul><li><p>Payment due within the terms shown above from the invoice date.</p></li><li><p>Bank details, or send a payment request from the share menu to collect by card or ACH.</p></li></ul><h2>Proof of work</h2><p><em><span style="color: rgb(140,148,162)">Matched pairs - same angle before and after. This is what stops invoice disputes.</span></em></p><h3>Area 1</h3><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EBefore%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Before"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EAfter%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="After"></p><h3>Area 2</h3><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EBefore%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Before"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EAfter%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="After"></p><h3>Waste &amp; PPE disposal</h3><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'720'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'719'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'360'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EDisposal%3C%2Ftext%3E%3Ctext%20x%3D'360'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="100%" height="260" alt="Disposal"></p><hr><p>Thanks for the work - questions on this invoice go to {{company_phone}}.</p><p><strong>Terms &amp; conditions</strong></p><p><em><span style="color: rgb(140,148,162)">Drop in your standard payment terms from the Snippets menu in the toolbar, or type them here once and save them as a snippet for next time.</span></em></p>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-crew-timesheet',
  NULL,
  NULL,
  'Weekly Crew Timesheet',
  jsonb_build_object(
    'style', 'report',
    'category', 'Field Admin',
    'description', 'Crew hours for one week with rates and totals, backed by photos showing the crew was on site and what they produced.',
    'html', $html$<h1>Weekly Crew Timesheet</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}} &nbsp;·&nbsp; Week ending {{date}}</span></p><hr><h2>Hours</h2><table><tbody><tr><th><p>Crew member</p></th><th><p>Role</p></th><th><p>Regular hrs</p></th><th><p>Overtime hrs</p></th><th><p>Rate</p></th><th><p>Total</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><table><tbody><tr><th><p></p></th><th><p>Amount</p></th></tr><tr><td><p><strong>Week total</strong></p></td><td><p>[Amount]</p></td></tr></tbody></table><h2>What the crew produced</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p></p></li><li data-type="taskItem" data-checked="false"><p></p></li><li data-type="taskItem" data-checked="false"><p></p></li></ul><h2>Materials &amp; plant used</h2><ul><li><p></p></li><li><p></p></li></ul><h2>Proof of attendance</h2><p><em><span style="color: rgb(140,148,162)">Enough to answer 'were they actually there' months later.</span></em></p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3ECrew%20on%20site%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Crew on site"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EWork%20in%20progress%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Work in progress"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EEnd%20of%20day%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="End of day"></p><hr><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Crew lead</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Supervisor</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-change-order-log',
  NULL,
  NULL,
  'Change Order Log',
  jsonb_build_object(
    'style', 'report',
    'category', 'Field Admin',
    'description', 'Every change against the contract in one register - cost, schedule impact, approval status, and the drawings that justify it.',
    'html', $html$<h1>Change Order Log</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><table><tbody><tr><th><p>Contract #</p></th><td><p>[Contract #]</p></td></tr><tr><th><p>Owner</p></th><td><p>[Owner]</p></td></tr><tr><th><p>General contractor / PM</p></th><td><p>[General contractor / PM]</p></td></tr><tr><th><p>Original contract value</p></th><td><p>[Original contract value]</p></td></tr></tbody></table><hr><h2>Changes</h2><p><em><span style="color: rgb(140,148,162)">One row per change, numbered. Keep it current - this register is what reconciles the final account.</span></em></p><table><tbody><tr><th><p>CO #</p></th><th><p>Description &amp; spec reference</p></th><th><p>Cost impact</p></th><th><p>Days impact</p></th><th><p>Status</p></th><th><p>Approved by</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Where it stands</h2><table><tbody><tr><th><p></p></th><th><p>Amount</p></th><th><p>Days</p></th></tr><tr><td><p>Drafted, not submitted</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Submitted, awaiting decision</p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Approved to date</strong></p></td><td><p><strong></strong></p></td><td><p><strong></strong></p></td></tr><tr><td><p><strong>Revised contract value</strong></p></td><td><p><strong></strong></p></td><td><p></p></td></tr></tbody></table><h2>Supporting evidence</h2><p><em><span style="color: rgb(140,148,162)">Marked-up drawings, site conditions, or anything that shows why the change was needed.</span></em></p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3ECondition%20driving%20the%20change%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Condition driving the change"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EMarked-up%20drawing%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Marked-up drawing"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EWork%20in%20question%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="260" alt="Work in question"></p><hr><h2>Approval</h2><p>Approval below authorises the changes marked approved in the register above.</p><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Owner / Rep</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Contractor PM</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><p><em><span style="color: rgb(140,148,162)">Send as a payment request from the share menu to invoice approved changes.</span></em></p>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-hvac-installation-startup',
  NULL,
  NULL,
  'HVAC Installation & Start-Up Report',
  jsonb_build_object(
    'style', 'report',
    'category', 'HVAC',
    'description', 'New equipment record for the warranty file: models and serials, install checklist, commissioning readings, airflow, and the customer walkthrough.',
    'html', $html$<h1>HVAC Installation and Start-Up</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><p><em><span style="color: rgb(140,148,162)">Everything the manufacturer wants on file for the warranty, in one page.</span></em></p><h2>Job details</h2><table><tbody><tr><th><p>Customer</p></th><th><p>Contact</p></th><th><p>Work order #</p></th><th><p>On site</p></th><th><p>Off site</p></th></tr><tr><td><p>[Customer name]</p></td><td><p>[Phone]</p></td><td><p>[WO number]</p></td><td><p>[Time]</p></td><td><p>[Time]</p></td></tr></tbody></table><h2>Equipment installed</h2><table><tbody><tr><th><p>Item</p></th><th><p>Make</p></th><th><p>Model</p></th><th><p>Serial</p></th><th><p>Warranty registered</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Equipment removed</h2><table><tbody><tr><th><p>Item</p></th><th><p>Make / model</p></th><th><p>Serial</p></th><th><p>Disposal</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Installation</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Line set pressure tested and held</p></li><li data-type="taskItem" data-checked="false"><p>System evacuated to 500 microns and held</p></li><li data-type="taskItem" data-checked="false"><p>Refrigerant charge weighed in and recorded</p></li><li data-type="taskItem" data-checked="false"><p>Condensate routed, trapped and draining</p></li><li data-type="taskItem" data-checked="false"><p>Disconnect and breaker sized to nameplate</p></li><li data-type="taskItem" data-checked="false"><p>Duct connections sealed and supported</p></li><li data-type="taskItem" data-checked="false"><p>Equipment level, secured and clear of obstruction</p></li><li data-type="taskItem" data-checked="false"><p>Thermostat installed and configured</p></li><li data-type="taskItem" data-checked="false"><p>New filter installed</p></li><li data-type="taskItem" data-checked="false"><p>Permit posted and inspection scheduled</p></li></ul><h2>Start-up readings</h2><table><tbody><tr><th><p>Reading</p></th><th><p>Value</p></th><th><p>Spec</p></th><th><p>In range</p></th></tr><tr><td><p>Line voltage (V)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Compressor amps (A)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Suction pressure (psi)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Head pressure (psi)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Superheat (°F)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Subcooling (°F)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Refrigerant charge (lb / oz)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Temperature split (Δ°F)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Total external static (in. w.c.)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Gas manifold pressure (in. w.c.)</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Airflow</h2><table><tbody><tr><th><p>Zone / register</p></th><th><p>Design CFM</p></th><th><p>Measured CFM</p></th><th><p>Balanced</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Photos</h2><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EIndoor%20unit%20installed%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Indoor unit installed"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EOutdoor%20unit%20installed%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Outdoor unit installed"></p><h2>Customer walkthrough</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Thermostat operation demonstrated</p></li><li data-type="taskItem" data-checked="false"><p>Filter type, size and change interval explained</p></li><li data-type="taskItem" data-checked="false"><p>Warranty terms and registration explained</p></li><li data-type="taskItem" data-checked="false"><p>Maintenance plan offered</p></li><li data-type="taskItem" data-checked="false"><p>Manuals and paperwork handed over</p></li></ul><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Installer</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Customer</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><p><span style="color: rgb(156,163,175)">{{company}} &nbsp;·&nbsp; {{company_address}} &nbsp;·&nbsp; {{company_phone}}</span></p>$html$
  ),
  ARRAY['company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;

